  ppsTelemetry.addNetPowerW(builder, NET_POWER_WOffset);
  ppsTelemetry.addBatteryStateOfCharge(builder, BATTERY_STATE_OF_CHARGEOffset);
  ppsTelemetry.addBatteryEnergyWh(builder, BATTERY_ENERGY_WHOffset);
  return ppsTelemetry.endppsTelemetry(builder);
